#include <iostream>
#include <vector>
using namespace std;

typedef long long int64;

int64 dfs(int i, int cnt, const string& t, const string& b, vector<vector<int64>>& memo);

string t, b;

int main() {
    t += '0';
    string a;
    cin >> a >> b;
    t += a;
    vector<vector<int64>> memo(t.size(), vector<int64>(b.size(), -1)); // Initialize memoization here
    cout << dfs(0, 0, t, b, memo) << endl; // Pass memo as an argument
    return 0;
}

int64 dfs(int i, int cnt, const string& t, const string& b, vector<vector<int64>>& memo) {
    int rec = 0;
    if (cnt == b.size()) return 1;
    if (memo[i][cnt] != -1) return memo[i][cnt];
    for (int j = i + 1; j < t.size(); j++) {
        if (t[j] == b[cnt]) rec = (rec + dfs(j, cnt + 1, t, b, memo)) % 1000000007; // Pass t and b as parameters
    }
    return memo[i][cnt] = rec % 1000000007;
}

